import { api, setCsrfToken, ApiError } from './api.js';
import { calculateInvoice, formatINR, GST_RATES } from '/shared/gst.js';
import { INDIAN_STATES } from '/shared/states.js';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const authShell = $('#auth-shell');
const appShell = $('#app-shell');
const pageContent = $('#page-content');
const modalRoot = $('#modal-root');
const state = { user: null, profile: null, page: 'dashboard', customers: [], products: [], invoices: [], productStockFilter: '', invoiceEditor: false };
const navItems = [['dashboard','Overview','⌂'],['invoices','Invoices','▤'],['customers','Customers','♙'],['products','Products','◇'],['reports','Reports','▥'],['settings','Business settings','⚙']];
const escapeHTML = (value = '') => String(value).replace(/[&<>"']/g, (ch) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[ch]);
const money = (value) => formatINR(value);
const dateText = (value) => value ? new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(value).slice(0,10)}T00:00:00`)) : '—';
const dateISO = () => new Date().toISOString().slice(0,10);
const initials = (name = '') => name.split(/\s+/).filter(Boolean).slice(0,2).map((x)=>x[0].toUpperCase()).join('') || 'U';
const navPath = (page,id='') => id ? `/invoices/${encodeURIComponent(id)}` : `/${page === 'dashboard' ? '' : page}`;
const toast = (message,kind='success') => { const node=document.createElement('div');node.className=`toast ${kind}`;node.textContent=message;$('#toast-root').append(node);setTimeout(()=>node.remove(),3600); };
const showError = (error) => toast(error instanceof ApiError ? error.message : 'We could not complete that action. Please try again.','error');
const statusBadge = (value='Draft') => { const key=String(value).toLowerCase(); return `<span class="badge ${escapeHTML(key)}">${escapeHTML(key.replaceAll('_',' ').replace(/^./,(c)=>c.toUpperCase()))}</span>`; };
const optionsForStates = (selected='') => `<option value="">Choose a state</option>${INDIAN_STATES.map((item)=>`<option value="${item.code}" data-name="${escapeHTML(item.name)}" ${String(selected)===item.code?'selected':''}>${escapeHTML(item.name)} · ${item.code}</option>`).join('')}`;
const selectedStateName = (code) => INDIAN_STATES.find((item)=>item.code===String(code))?.name || '';

function showAuth(mode='login', message='') {
  appShell.hidden=true;authShell.hidden=false;authShell.dataset.mode=mode;
  const heading=mode==='register'?'Create your account':mode==='otp'?'Verify your email':mode==='forgot'?'Reset your password':mode==='reset'?'Choose a new password':'Sign in to your account';
  let form='';
  if(mode==='login') form=`<div id="auth-message" class="auth-message">${escapeHTML(message)}</div><form id="login-form"><div class="form-grid"><div class="form-field full"><label for="login-email">Email address</label><input id="login-email" name="email" type="email" autocomplete="email" required></div><div class="form-field full"><label for="login-password">Password</label><input id="login-password" name="password" type="password" autocomplete="current-password" minlength="8" required></div></div><div style="text-align:right;margin-top:12px"><button class="text-button" type="button" data-action="forgot">Forgot password?</button></div><button class="btn btn-primary" style="width:100%;margin-top:18px" type="submit">Sign in</button></form><p class="auth-switch">New to GST Desk? <button class="text-button" data-action="show-register">Create an account</button></p>`;
  else if(mode==='register') form=`<div id="auth-message" class="auth-message">${escapeHTML(message)}</div><form id="register-form"><div class="form-grid"><div class="form-field full"><label for="register-name">Your name</label><input id="register-name" name="name" autocomplete="name" required maxlength="120"></div><div class="form-field full"><label for="register-email">Email address</label><input id="register-email" name="email" type="email" autocomplete="email" required></div><div class="form-field full"><label for="register-mobile">Mobile number</label><input id="register-mobile" name="mobile" type="tel" autocomplete="tel" required></div><div class="form-field full"><label for="register-password">Password</label><input id="register-password" name="password" type="password" autocomplete="new-password" minlength="8" required><small>Use at least 8 characters.</small></div></div><button class="btn btn-primary" style="width:100%;margin-top:20px" type="submit">Create account</button></form><p class="auth-switch">Already have an account? <button class="text-button" data-action="show-login">Sign in</button></p>`;
  else if(mode==='otp') form=`<div id="auth-message" class="auth-message">${escapeHTML(message)}</div><form id="otp-form"><div class="form-field"><label for="otp-code">Six-digit verification code</label><input id="otp-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></div><button class="btn btn-primary" style="width:100%;margin-top:18px" type="submit">Verify and sign in</button></form><p class="auth-switch"><button class="text-button" data-action="resend-otp">Resend code</button></p>`;
  else if(mode==='forgot') form=`<p class="sub">Enter your account email. If email delivery is configured, we’ll send a secure reset code.</p><div id="auth-message" class="auth-message">${escapeHTML(message)}</div><form id="forgot-form"><div class="form-field"><label for="forgot-email">Email address</label><input id="forgot-email" name="email" type="email" required></div><button class="btn btn-primary" style="width:100%;margin-top:18px" type="submit">Send reset code</button></form><p class="auth-switch"><button class="text-button" data-action="show-login">Back to sign in</button></p>`;
  else form=`<p class="sub">Enter the code sent to your email and choose a new password.</p><div id="auth-message" class="auth-message">${escapeHTML(message)}</div><form id="reset-form"><div class="form-grid"><div class="form-field full"><label for="reset-email">Email address</label><input id="reset-email" name="email" type="email" required></div><div class="form-field full"><label for="reset-code">Reset code</label><input id="reset-code" name="code" autocomplete="one-time-code" required></div><div class="form-field full"><label for="reset-password">New password</label><input id="reset-password" name="password" type="password" minlength="8" required></div></div><button class="btn btn-primary" style="width:100%;margin-top:18px" type="submit">Update password</button></form><p class="auth-switch"><button class="text-button" data-action="show-login">Back to sign in</button></p>`;
  authShell.innerHTML=`<section class="auth-aside"><div class="auth-brand"><span class="brand-mark">▤</span><span>GST Desk</span></div><div><h1>Billing made clear.</h1><p>Every invoice, tax split and customer record—organized in one calm, simple workspace.</p></div><div class="hint">Built for the everyday work of Indian small businesses.</div></section><section class="auth-main"><div class="auth-card"><div class="auth-brand" style="margin-bottom:24px"><span class="brand-mark">▤</span><span>GST Desk</span></div><h2>${heading}</h2>${mode==='login'||mode==='register'||mode==='otp'?'': ''}${form}${mode==='login'?'':'<p class="auth-foot">Your business data stays private to your account.</p>'}</div></section>`;
}

function renderSidebar() {
  $('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">▤</span><span>GST Desk<small>Billing workspace</small></span></div><div class="nav-label">Workspace</div><nav class="nav-list">${navItems.map(([id,label,icon])=>`<button class="nav-link ${state.page===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="account-mini"><span class="avatar">${escapeHTML(initials(state.user?.name))}</span><div><strong>${escapeHTML(state.user?.name||'Account')}</strong><small>${escapeHTML(state.user?.email||'')}</small></div></div><button class="nav-link" data-action="logout" style="margin-top:12px"><span class="nav-icon">↪</span>Sign out</button>`;
  const title=state.page==='invoice-detail'?'Invoice details':(navItems.find(([id])=>id===state.page)?.[1]||'Overview');
  $('#topbar').innerHTML=`<div class="topbar-main"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div><h1>${escapeHTML(title)}</h1><p>${state.profile?.businessName?escapeHTML(state.profile.businessName):'Set up your business profile to personalize invoices'}</p></div></div><div class="topbar-actions"><button class="btn btn-primary" data-action="new-invoice">＋ New invoice</button></div>`;
}
async function bootstrap() {
  try {
    const result=await api.get('/api/auth/me');setCsrfToken(result.csrfToken);state.user=result.user;state.profile=result.profile;
    const parts=location.pathname.split('/').filter(Boolean);
    if(parts[0]==='invoices'&&parts[1]){state.page='invoice-detail';enterApp(decodeURIComponent(parts[1]));}
    else {state.page=parts[0]||'dashboard';if(!navItems.some(([id])=>id===state.page))state.page='dashboard';enterApp();}
  } catch { showAuth(location.pathname==='/register'?'register':'login'); }
}
function enterApp(id='') {authShell.hidden=true;appShell.hidden=false;renderSidebar();navigate(state.page,id,false);}
async function navigate(page,id='',push=true) {
  state.page=page;if(push)history.pushState({page,id},'',id?navPath(page,id):navPath(page));renderSidebar();$('#sidebar').classList.remove('open');$('.mobile-overlay')?.classList.remove('show');
  try {if(page==='dashboard')await renderDashboard();else if(page==='customers')await renderCustomers();else if(page==='products')await renderProducts();else if(page==='invoices')await renderInvoices();else if(page==='reports')await renderReports();else if(page==='settings')await renderSettings();else if(page==='invoice-detail')await renderInvoiceDetail(id);}
  catch(error){showError(error);pageContent.innerHTML=`<div class="card empty-state"><h3>We couldn't load this page</h3><p>${escapeHTML(error.message)}</p><button class="btn btn-secondary" data-action="retry">Try again</button></div>`;}
  pageContent.focus({preventScroll:true});
}
const heading=(title,subtitle,action='')=>`<div class="page-heading"><div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(subtitle)}</p></div>${action}</div>`;
const emptyState=(icon,title,text,action='')=>`<div class="empty-state"><div class="empty-icon">${icon}</div><h3>${escapeHTML(title)}</h3><p>${escapeHTML(text)}</p>${action}</div>`;
const tableRows=(items,render,empty)=>items.length?items.map(render).join(''):`<tr><td colspan="10" style="text-align:center;padding:28px;color:#94a3b8">${escapeHTML(empty)}</td></tr>`;

async function renderDashboard() {
  const data=await api.get('/api/dashboard');state.profile=data.profile||state.profile;const stats=data.stats||{};const recent=data.recentInvoices||[];
  pageContent.innerHTML=`${!state.profile?.businessName?`<div class="notice"><div><strong>Set up your business profile</strong>Add your business name, address and state to start issuing personalized GST invoices. <button class="text-button" data-nav="settings">Open business settings →</button></div></div>`:''}${heading(`Good day, ${state.user?.name?.split(' ')[0]||'there'}`,'Here is your business at a glance.')}<div class="stats-grid">${[['Total sales',money(stats.totalSales),'↗'],['Invoices',stats.invoiceCount??0,'▤'],['Customers',stats.customerCount??0,'♙'],['Products',stats.productCount??0,'◇'],['GST collected',money(stats.totalGst),'₹']].map(([label,value,icon])=>`<article class="stat-card"><div class="stat-label">${label}<span>${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">Based on finalized invoices</div></article>`).join('')}</div><div class="dashboard-columns"><section class="card"><div class="card-heading"><div><h3>Monthly sales</h3><p>Sales from finalized invoices this year</p></div><span class="badge">${new Date().getFullYear()}</span></div><div class="chart-wrap">${renderChart(data.monthlySales||[])}</div></section><section class="card"><div class="card-heading"><div><h3>Quick actions</h3><p>Keep your business moving</p></div></div><div class="quick-actions"><button class="quick-action" data-action="new-invoice"><span class="quick-icon">＋</span><span><strong>Create new invoice</strong><small>Start a GST invoice</small></span></button><button class="quick-action" data-action="add-customer"><span class="quick-icon">♙</span><span><strong>Add customer</strong><small>Save billing details once</small></span></button><button class="quick-action" data-action="add-product"><span class="quick-icon">◇</span><span><strong>Add product</strong><small>Keep your item list ready</small></span></button><button class="quick-action" data-nav="invoices"><span class="quick-icon">▤</span><span><strong>View all invoices</strong><small>Search and update payments</small></span></button></div></section></div><section class="card" style="margin-top:16px"><div class="card-heading"><div><h3>Recent invoices</h3><p>Your latest saved invoices</p></div><button class="text-button" data-nav="invoices">View all</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th>Amount</th><th>Payment</th><th></th></tr></thead><tbody>${tableRows(recent,(invoice)=>`<tr><td class="strong">${escapeHTML(invoice.invoiceNumber)}</td><td>${escapeHTML(invoice.customerName||'Walk-in customer')}</td><td>${dateText(invoice.invoiceDate)}</td><td>${money(invoice.grandTotal)}</td><td>${statusBadge(invoice.paymentStatus)}</td><td><button class="text-button" data-view-invoice="${escapeHTML(invoice.id)}">View</button></td></tr>`,'No invoices yet — your saved invoices will appear here.')}</tbody></table></div>${recent.length?'':emptyState('▤','No invoices yet','Create an invoice to see real sales and GST totals here.','<button class="btn btn-primary" data-action="new-invoice">Create first invoice</button>')}</section>`;
}
function renderChart(values) {
  const entries=Array.from({length:12},(_,i)=>values[i]||{label:new Date(2000,i,1).toLocaleString('en',{month:'short'}),total:0});const max=Math.max(1,...entries.map((v)=>Number(v.total||0)));const points=entries.map((v,i)=>`${30+i*52},${196-(Number(v.total||0)/max)*164}`).join(' ');const area=`30,196 ${points} 602,196`;
  return `<svg viewBox="0 0 630 232" role="img" aria-label="Monthly sales chart"><line class="chart-grid" x1="24" y1="32" x2="610" y2="32"/><line class="chart-grid" x1="24" y1="86" x2="610" y2="86"/><line class="chart-grid" x1="24" y1="141" x2="610" y2="141"/><line class="chart-grid" x1="24" y1="196" x2="610" y2="196"/><polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${points}"/>${entries.map((v,i)=>`<text class="chart-label" x="${20+i*52}" y="220">${escapeHTML(v.label)}</text>`).join('')}</svg>`;
}

async function renderCustomers(search='') {
  const data=await api.get(`/api/customers?search=${encodeURIComponent(search)}`);state.customers=data.customers||[];
  pageContent.innerHTML=`${heading('Customers','Keep billing details ready for the next invoice.','<button class="btn btn-primary" data-action="add-customer">＋ Add customer</button>')}<section class="card"><div class="toolbar"><input data-search="customers" placeholder="Search by name, mobile or GSTIN" value="${escapeHTML(search)}" aria-label="Search customers"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Mobile</th><th>GSTIN</th><th>State</th><th>Invoices</th><th>Actions</th></tr></thead><tbody>${tableRows(state.customers,(c)=>`<tr><td class="strong">${escapeHTML(c.name)}</td><td>${escapeHTML(c.mobile)}</td><td>${escapeHTML(c.gstin||'Unregistered')}</td><td>${escapeHTML(c.state||'—')}</td><td>${Number(c.invoiceCount||0)}</td><td><div class="table-actions"><button class="btn btn-secondary btn-small" data-customer-history="${escapeHTML(c.id)}">History</button><button class="btn btn-secondary btn-small" data-edit-customer="${escapeHTML(c.id)}">Edit</button><button class="btn btn-danger btn-small" data-remove-customer="${escapeHTML(c.id)}">Delete</button></div></td></tr>`,'No customers found. Add your first customer to begin.')}</tbody></table></div>${state.customers.length?'':emptyState('♙','No customers yet','Save a customer once and their billing details are ready for every invoice.','<button class="btn btn-primary" data-action="add-customer">Add first customer</button>')}</section>`;
}
async function editCustomer(id='new') {
  const c=id==='new'?{}:state.customers.find((row)=>row.id===id)||((await api.get('/api/customers')).customers||[]).find((row)=>row.id===id)||{};
  const fields=`<form id="customer-form" data-submit="customer" data-id="${escapeHTML(c.id||'')}"><div class="form-grid"><div class="form-field full"><label for="cust-name">Customer name *</label><input id="cust-name" name="name" value="${escapeHTML(c.name||'')}" required maxlength="180"></div><div class="form-field"><label for="cust-mobile">Mobile number *</label><input id="cust-mobile" name="mobile" type="tel" value="${escapeHTML(c.mobile||'')}" required></div><div class="form-field"><label for="cust-email">Email address</label><input id="cust-email" name="email" type="email" value="${escapeHTML(c.email||'')}"></div><div class="form-field full"><label for="cust-address">Billing address</label><textarea id="cust-address" name="address">${escapeHTML(c.address||'')}</textarea></div><div class="form-field"><label for="cust-state">State</label><select id="cust-state" name="stateCode">${optionsForStates(c.stateCode)}</select></div><div class="form-field"><label for="cust-gstin">GSTIN</label><input id="cust-gstin" name="gstin" value="${escapeHTML(c.gstin||'')}" maxlength="15" placeholder="15-character GSTIN" ${c.customerType==='registered'?'required':''}></div><div class="form-field"><label for="cust-type">Customer type</label><select id="cust-type" name="customerType"><option value="unregistered" ${c.customerType!=='registered'?'selected':''}>Unregistered</option><option value="registered" ${c.customerType==='registered'?'selected':''}>Registered</option></select></div></div><p class="hint">State code is used to calculate CGST/SGST or IGST automatically.</p><div class="form-actions"><button class="btn btn-secondary" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${id==='new'?'Add customer':'Save changes'}</button></div></form>`;
  openModal(id==='new'?'Add customer':'Edit customer',fields);
}
async function saveCustomer(form,values) {
  const code=values.stateCode||'';values.stateCode=code;values.state=selectedStateName(code);const id=form.dataset.id;
  if(id)await api.put(`/api/customers/${id}`,values);else await api.post('/api/customers',values);
  closeModal();toast(id?'Customer updated.':'Customer added.');await renderCustomers();
}
async function removeCustomer(id) { if(!confirm('Delete this customer? Saved invoices will keep their original billing details.'))return;try{await api.delete(`/api/customers/${id}`);toast('Customer deleted.');await renderCustomers();}catch(error){showError(error);} }
async function showCustomerHistory(id) {
  try {
    const customer = state.customers.find((row) => row.id === id);
    const data = await api.get('/api/invoices');
    const rows = (data.invoices || []).filter((invoice) => invoice.customerId === id);
    const details = customer ? `<div class="detail-list" style="margin-bottom:18px"><div><span>Mobile</span><strong>${escapeHTML(customer.mobile || '—')}</strong></div><div><span>Email</span><strong>${escapeHTML(customer.email || '—')}</strong></div><div><span>Billing address</span><strong>${escapeHTML(customer.address || '—')}</strong></div><div><span>State</span><strong>${escapeHTML(customer.state || '—')}${customer.stateCode ? ` · ${escapeHTML(customer.stateCode)}` : ''}</strong></div><div><span>Customer type</span><strong>${escapeHTML(customer.customerType || 'unregistered')}</strong></div><div><span>GSTIN</span><strong>${escapeHTML(customer.gstin || '—')}</strong></div></div>` : '';
    const history = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((invoice) => `<tr><td class="strong">${escapeHTML(invoice.invoiceNumber)}</td><td>${dateText(invoice.invoiceDate)}</td><td>${money(invoice.grandTotal)}</td><td>${statusBadge(invoice.paymentStatus)}</td><td><button class="text-button" data-view-invoice="${escapeHTML(invoice.id)}">View</button></td></tr>`).join('')}</tbody></table></div>` : emptyState('▤', 'No invoices yet', 'Invoices for this customer will show here.');
    openModal(`${customer?.name || 'Customer'} · details & invoice history`, `${details}${history}`);
  } catch (error) { showError(error); }
}

async function renderProducts(search='') {
  const data=await api.get(`/api/products?search=${encodeURIComponent(search)}`);state.products=data.products||[];const productRows=state.productStockFilter==='low'?state.products.filter((p)=>Number(p.stock)<=5):state.products;
  pageContent.innerHTML=`${heading('Products & inventory','Maintain the items you sell and their GST rates.','<button class="btn btn-primary" data-action="add-product">＋ Add product</button>')}<section class="card"><div class="toolbar"><input data-search="products" placeholder="Search by product or HSN/SAC" value="${escapeHTML(search)}" aria-label="Search products"><select data-filter="stock"><option value="">All stock levels</option><option value="low" ${state.productStockFilter==='low'?'selected':''}>Low stock (5 or less)</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>HSN/SAC</th><th>Price</th><th>GST</th><th>Unit</th><th>Available stock</th><th>Actions</th></tr></thead><tbody>${tableRows(productRows,(p)=>`<tr><td class="strong">${escapeHTML(p.name)}${p.description?`<div class="hint">${escapeHTML(p.description)}</div>`:''}</td><td>${escapeHTML(p.hsn||'—')}</td><td>${money(p.price)}</td><td>${Number(p.gstRate)}%</td><td>${escapeHTML(p.unit)}</td><td>${Number(p.stock)} ${escapeHTML(p.unit)} ${Number(p.stock)<=5?'<span class="badge pending">Low</span>':''}</td><td><div class="table-actions"><button class="btn btn-secondary btn-small" data-view-product="${escapeHTML(p.id)}">View</button><button class="btn btn-secondary btn-small" data-edit-product="${escapeHTML(p.id)}">Edit</button><button class="btn btn-danger btn-small" data-remove-product="${escapeHTML(p.id)}">Delete</button></div></td></tr>`,'No products found. Add your first item to use it in an invoice.')}</tbody></table></div>${productRows.length?'':emptyState('◇','No products yet','Add the products you sell. Their price, HSN and GST rate will fill in automatically on invoices.','<button class="btn btn-primary" data-action="add-product">Add first product</button>')}</section>`;
}
async function showProductDetails(id) {
  if (!state.products.length) state.products = (await api.get('/api/products')).products || [];
  const product = state.products.find((row) => row.id === id);
  if (!product) return toast('Product not found.', 'error');
  openModal(product.name, `<div class="detail-list"><div><span>Description</span><strong>${escapeHTML(product.description||'—')}</strong></div><div><span>HSN/SAC</span><strong>${escapeHTML(product.hsn||'—')}</strong></div><div><span>Price</span><strong>${money(product.price)}</strong></div><div><span>GST rate</span><strong>${Number(product.gstRate)}%</strong></div><div><span>Unit</span><strong>${escapeHTML(product.unit)}</strong></div><div><span>Available stock</span><strong>${Number(product.stock)} ${escapeHTML(product.unit)}</strong></div></div>`);
}
async function editProduct(id='new') {
  if(!state.products.length&&id!=='new')state.products=(await api.get('/api/products')).products||[];
  const p=id==='new'?{}:state.products.find((row)=>row.id===id)||{};
  const content=`<form id="product-form" data-submit="product" data-id="${escapeHTML(p.id||'')}"><div class="form-grid"><div class="form-field full"><label for="prod-name">Product name *</label><input id="prod-name" name="name" value="${escapeHTML(p.name||'')}" required maxlength="180"></div><div class="form-field full"><label for="prod-desc">Description</label><textarea id="prod-desc" name="description">${escapeHTML(p.description||'')}</textarea></div><div class="form-field"><label for="prod-hsn">HSN/SAC code</label><input id="prod-hsn" name="hsn" value="${escapeHTML(p.hsn||'')}"></div><div class="form-field"><label for="prod-price">Price per unit (₹) *</label><input id="prod-price" name="price" type="number" min="0" step="0.01" value="${escapeHTML(p.price??'')}" required></div><div class="form-field"><label for="prod-gst">GST rate *</label><select id="prod-gst" name="gstRate" required>${GST_RATES.map((rate)=>`<option value="${rate}" ${Number(p.gstRate||0)===rate?'selected':''}>${rate}%</option>`).join('')}</select></div><div class="form-field"><label for="prod-unit">Unit *</label><input id="prod-unit" name="unit" value="${escapeHTML(p.unit||'pcs')}" required></div><div class="form-field"><label for="prod-stock">Available stock *</label><input id="prod-stock" name="stock" type="number" min="0" step="0.001" value="${escapeHTML(p.stock??'0')}" required></div></div><div class="form-actions"><button class="btn btn-secondary" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">${id==='new'?'Add product':'Save changes'}</button></div></form>`;
  openModal(id==='new'?'Add product':'Edit product',content);
}
async function saveProduct(form,values) {const id=form.dataset.id;if(id)await api.put(`/api/products/${id}`,values);else await api.post('/api/products',values);closeModal();toast(id?'Product updated.':'Product added.');await renderProducts();}
