function buildInvoicePayload() {
  const cust=readCustomerForm();return {...cust,invoiceDate:$('#inv-date')?.value||dateISO(),dueDate:$('#inv-due')?.value||'',docType:$('#inv-type')?.value||'tax_invoice',placeOfSupply:$('#inv-place')?.value||selectedStateName(cust.customer.stateCode),otherCharges:Number($('#inv-charges')?.value||0),additionalDiscount:Number($('#inv-discount')?.value||0),roundOff:Number($('#inv-round')?.value||0),notes:$('#inv-notes')?.value||'',terms:$('#inv-terms')?.value||'',items:readInvoiceLines()};
}
function recalculateEditor() {
  if(!$('#invoice-form'))return;const payload=buildInvoicePayload();const intra=Boolean(state.profile?.stateCode&&payload.customer.stateCode&&String(state.profile.stateCode)===String(payload.customer.stateCode));const totals=calculateInvoice(payload.items,{intraState:intra,otherCharges:payload.otherCharges,additionalDiscount:payload.additionalDiscount,roundOff:payload.roundOff});
  $$('.invoice-line').forEach((row,index)=>{const line=totals.lines[index];const taxable=row.querySelector('[data-line-taxable]');const gst=row.querySelector('[data-line-gst]');const total=row.querySelector('[data-line-total]');if(taxable)taxable.textContent=money(line?.taxable||0);if(gst)gst.textContent=money(line?.gstAmount||0);if(total)total.textContent=money(line?.total||0);});
  $('#gst-mode-label').textContent=$('#inv-type')?.value==='bill_of_supply'?'Bill of Supply · no GST charged':(payload.customer.stateCode?`${intra?'Intra-state · CGST + SGST':'Inter-state · IGST'}`:'Select customer state for tax split');
  $('#invoice-totals').innerHTML=`<div class="totals-row"><span>Subtotal</span><strong>${money(totals.subtotal)}</strong></div><div class="totals-row"><span>Item discounts</span><strong>− ${money(totals.totalDiscount-totals.additionalDiscount)}</strong></div><div class="totals-row"><span>Taxable value</span><strong>${money(totals.taxableValue)}</strong></div>${intra?`<div class="totals-row"><span>CGST</span><strong>${money(totals.cgst)}</strong></div><div class="totals-row"><span>SGST</span><strong>${money(totals.sgst)}</strong></div>`:`<div class="totals-row"><span>IGST</span><strong>${money(totals.igst)}</strong></div>`}<div class="totals-row"><span>Other charges</span><strong>${money(totals.otherCharges)}</strong></div><div class="totals-row"><span>Additional discount</span><strong>− ${money(totals.additionalDiscount)}</strong></div><div class="totals-row"><span>Round-off</span><strong>${money(totals.roundOff)}</strong></div><div class="totals-row grand"><span>Grand total</span><strong>${money(totals.grandTotal)}</strong></div>`;
}
function syncCustomerSelection() {
  const id=$('#inv-customer')?.value;const customer=state.customers.find((row)=>row.id===id);if(!customer)return;
  $('#inv-cust-name').value=customer.name||'';$('#inv-cust-mobile').value=customer.mobile||'';$('#inv-cust-email').value=customer.email||'';$('#inv-cust-address').value=customer.address||'';$('#inv-cust-state').value=customer.stateCode||'';$('#inv-cust-gstin').value=customer.gstin||'';$('#inv-cust-type').value=customer.customerType||'unregistered';$('#inv-cust-gstin').required=$('#inv-cust-type').value==='registered';if(!$('#inv-place').value)$('#inv-place').value=customer.state||'';recalculateEditor();
}
function syncProductSelection(select) {
  const product=state.products.find((row)=>row.id===select.value);if(!product)return;const row=select.closest('.invoice-line');row.querySelector('[data-line-field="name"]').value=product.name;row.querySelector('[data-line-field="hsn"]').value=product.hsn||'';row.querySelector('[data-line-field="unitPrice"]').value=product.price;row.querySelector('[data-line-field="gstRate"]').value=$('#inv-type')?.value==='bill_of_supply'?'0':String(Number(product.gstRate));row.querySelector('[data-line-field="unit"]').value=product.unit||'pcs';row.dataset.unit=product.unit||'pcs';row.dataset.description=product.description||'';recalculateEditor();
}
function addInvoiceLine() {const body=$('#invoice-lines');if(!body)return;body.insertAdjacentHTML('beforeend',renderItemLine($$('.invoice-line').length,{quantity:1}));syncDocumentType();}
function syncDocumentType() { const bill=$('#inv-type')?.value==='bill_of_supply';$$('.invoice-line [data-line-field="gstRate"]').forEach((field)=>{field.disabled=bill;if(bill)field.value='0';});recalculateEditor(); }
function previewInvoice() {
  const payload=buildInvoicePayload();if(!payload.customer.name||!payload.customer.stateCode)return toast('Enter the customer name and state to preview GST.','error');if(!payload.items.some((item)=>item.name&&item.quantity>0))return toast('Add at least one item before previewing.','error');
  const intra=String(state.profile?.stateCode)===String(payload.customer.stateCode);const totals=calculateInvoice(payload.items,{intraState:intra,otherCharges:payload.otherCharges,additionalDiscount:payload.additionalDiscount,roundOff:payload.roundOff});
  const business={businessName:state.profile?.businessName||'Your business',address:state.profile?.address||'',gstin:state.profile?.gstin||'',state:state.profile?.state||'',stateCode:state.profile?.stateCode||'',contactNumber:state.profile?.contactNumber||'',email:state.profile?.email||'',bankDetails:state.profile?.bankDetails||{},logoUrl:state.profile?.logoUrl||''};
  openModal('Invoice preview',`${renderInvoiceDocument({invoiceNumber:'Assigned when saved',invoiceDate:payload.invoiceDate,dueDate:payload.dueDate,placeOfSupply:payload.placeOfSupply,docType:payload.docType,paymentStatus:'unpaid',notes:payload.notes,terms:payload.terms,...totals,business,customer:payload.customer},totals.lines)}<div class="form-actions no-print"><button class="btn btn-secondary" type="button" data-action="close-modal">Keep editing</button><button class="btn btn-primary" type="button" data-action="save-invoice">Save draft</button></div>`,true);
}
async function saveInvoiceFromEditor() {
  const form=$('#invoice-form');if(!form)return;const payload=buildInvoicePayload();if(!form.reportValidity())return;
  try{const result=await api.post('/api/invoices',payload);state.invoiceEditor=false;closeModal();toast(`Draft ${result.invoiceNumber} saved.`);await navigate('invoice-detail',result.id);}catch(error){showError(error);}
}

function amountWords(value) {
  const number=Math.round(Number(value||0)*100)/100;const rupees=Math.floor(number),paise=Math.round((number-rupees)*100);const one=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];const tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const two=(n)=>n<20?one[n]:`${tens[Math.floor(n/10)]}${n%10?` ${one[n%10]}`:''}`;const three=(n)=>`${n>=100?`${one[Math.floor(n/100)]} Hundred${n%100?' ':''}`:''}${n%100?two(n%100):''}`.trim();let rest=rupees;const parts=[];for(const [div,label] of [[10000000,'Crore'],[100000,'Lakh'],[1000,'Thousand']]){const group=Math.floor(rest/div);if(group)parts.push(`${two(group)} ${label}`);rest%=div;}if(rest)parts.push(three(rest));return `${parts.join(' ')||'Zero'} Rupees${paise?` and ${two(paise)} Paise`:''} Only`;
}
function renderInvoiceDocument(invoice,items=[]) {
  const business=invoice.business||{};const customer=invoice.customer||{};const intra=Boolean(invoice.intraState);
  const lines=items.map((item,index)=>`<tr><td>${index+1}. ${escapeHTML(item.name)}${item.description?`<div class="hint">${escapeHTML(item.description)}</div>`:''}</td><td>${escapeHTML(item.hsn||'—')}</td><td>${Number(item.quantity)} ${escapeHTML(item.unit||'')}</td><td>${money(item.unitPrice)}</td><td>${money(item.discount||0)}</td><td>${money(item.taxable)}</td><td>${Number(item.gstRate)}%</td><td>${money(item.gstAmount||0)}</td><td>${money(item.total)}</td></tr>`).join('');
  const cgst=Number(invoice.cgst||items.reduce((n,item)=>n+Number(item.cgst||0),0));const sgst=Number(invoice.sgst||items.reduce((n,item)=>n+Number(item.sgst||0),0));const igst=Number(invoice.igst||items.reduce((n,item)=>n+Number(item.igst||0),0));
  const bank=business.bankDetails||{};
  return `<article class="document"><div class="doc-header"><div><img class="doc-logo" src="${escapeHTML(business.logoUrl||'/logo.svg')}" alt="Business logo"><h2>${escapeHTML(business.businessName||'Business name')}</h2><p style="font-size:11px;line-height:1.5">${escapeHTML(business.address||'Business address')}<br>${escapeHTML(business.state||'')}${business.stateCode?` · State code ${escapeHTML(business.stateCode)}`:''}<br>${business.gstin?`GSTIN: ${escapeHTML(business.gstin)}<br>`:''}${escapeHTML(business.contactNumber||'')}${business.email?` · ${escapeHTML(business.email)}`:''}</p></div><div style="text-align:right"><span class="badge">${invoice.docType==='bill_of_supply'?'BILL OF SUPPLY':'TAX INVOICE'}</span><p style="font-size:12px;margin:12px 0 4px"><strong>Invoice no.</strong> ${escapeHTML(invoice.invoiceNumber||'')}</p><p style="font-size:11px;margin:4px 0"><strong>Date:</strong> ${dateText(invoice.invoiceDate)}</p>${invoice.dueDate?`<p style="font-size:11px;margin:4px 0"><strong>Due:</strong> ${dateText(invoice.dueDate)}</p>`:''}<p style="font-size:11px;margin:4px 0"><strong>Payment:</strong> ${escapeHTML(String(invoice.paymentStatus||'unpaid').replaceAll('_',' '))}</p></div></div><div class="doc-section doc-grid"><div><h4>Bill to</h4><p><strong>${escapeHTML(customer.name||'Customer')}</strong><br>${escapeHTML(customer.address||'')}${customer.state?`<br>${escapeHTML(customer.state)}${customer.stateCode?` · ${escapeHTML(customer.stateCode)}`:''}`:''}${customer.gstin?`<br>GSTIN: ${escapeHTML(customer.gstin)}`:''}${customer.mobile?`<br>Mobile: ${escapeHTML(customer.mobile)}`:''}${customer.email?`<br>${escapeHTML(customer.email)}`:''}</p></div><div><h4>Supply details</h4><p>Place of supply: ${escapeHTML(invoice.placeOfSupply||customer.state||'—')}<br>Tax treatment: ${invoice.docType==='bill_of_supply'?'No GST charged · Bill of Supply':(intra?'Intra-state · CGST + SGST':'Inter-state · IGST')}</p></div></div><div class="table-wrap"><table class="doc-table"><thead><tr><th>Item</th><th>HSN/SAC</th><th>Qty</th><th>Unit price</th><th>Discount</th><th>Taxable</th><th>GST rate</th><th>GST amount</th><th>Total</th></tr></thead><tbody>${lines||'<tr><td colspan="9">No line items.</td></tr>'}</tbody></table></div><div class="doc-totals"><div class="totals-row"><span>Subtotal</span><strong>${money(invoice.subtotal||0)}</strong></div><div class="totals-row"><span>Total discount</span><strong>− ${money(invoice.totalDiscount||0)}</strong></div><div class="totals-row"><span>Taxable value</span><strong>${money(invoice.taxableValue||0)}</strong></div>${intra?`<div class="totals-row"><span>CGST</span><strong>${money(cgst)}</strong></div><div class="totals-row"><span>SGST</span><strong>${money(sgst)}</strong></div>`:`<div class="totals-row"><span>IGST</span><strong>${money(igst)}</strong></div>`}<div class="totals-row"><span>Other charges</span><strong>${money(invoice.otherCharges||0)}</strong></div><div class="totals-row"><span>Round-off</span><strong>${money(invoice.roundOff||0)}</strong></div><div class="totals-row grand"><span>Amount payable</span><strong>${money(invoice.grandTotal||0)}</strong></div></div><div class="doc-amount-words"><strong>Amount in words:</strong> ${escapeHTML(amountWords(invoice.grandTotal||0))}</div>${invoice.notes?`<div class="doc-section"><strong style="font-size:11px">Notes</strong><p style="font-size:11px">${escapeHTML(invoice.notes)}</p></div>`:''}${invoice.terms?`<div class="doc-section"><strong style="font-size:11px">Terms and conditions</strong><p style="font-size:11px;white-space:pre-wrap">${escapeHTML(invoice.terms)}</p></div>`:''}${bank.bankName||bank.bankAccount?`<div class="doc-section"><strong style="font-size:11px">Bank details</strong><p style="font-size:11px">${escapeHTML(bank.bankName||'')}${bank.bankAccount?` · ${escapeHTML(bank.bankAccount)}`:''}${bank.bankIfsc?` · IFSC ${escapeHTML(bank.bankIfsc)}`:''}</p></div>`:''}<div class="doc-footer"><div>Thank you for your business.</div><div style="text-align:center;min-width:170px;padding-top:34px;border-top:1px solid #64748b">Authorized signature</div></div></article>`;
}
async function renderInvoiceDetail(id) {
  const data=await api.get(`/api/invoices/${encodeURIComponent(id)}`);const invoice=data.invoice;const items=data.items||[];state.currentInvoice=invoice;state.currentInvoiceItems=items;
  const buttons=`<div class="table-actions no-print"><button class="btn btn-secondary" data-action="download-pdf" data-id="${escapeHTML(id)}">Download PDF</button><button class="btn btn-secondary" data-action="print-invoice">Print</button>${invoice.status==='draft'?`<button class="btn btn-primary" data-invoice-action="finalize" data-id="${escapeHTML(id)}">Finalize invoice</button>`:''}${invoice.status!=='cancelled'?`<button class="btn btn-danger" data-invoice-action="cancel" data-id="${escapeHTML(id)}">Cancel invoice</button>`:''}${invoice.status==='finalized'?`<button class="btn btn-secondary" data-invoice-action="payment" data-id="${escapeHTML(id)}">Record payment</button><select aria-label="Update payment status" data-payment-status="${escapeHTML(id)}"><option value="">Payment status</option><option value="paid">Paid</option><option value="partially_paid">Partially paid</option><option value="unpaid">Unpaid</option></select>`:''}</div>`;
  pageContent.innerHTML=`${heading(invoice.invoiceNumber,`Invoice date ${dateText(invoice.invoiceDate)} · ${String(invoice.status).replaceAll('_',' ')}`,`<button class="btn btn-secondary" data-nav="invoices">← Back to invoices</button>`)}<div class="card" style="margin-bottom:16px;display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div>${statusBadge(invoice.status)} ${statusBadge(invoice.paymentStatus)} <span class="hint" style="margin-left:8px">${money(invoice.grandTotal)} total · ${money(invoice.amountPaid)} paid</span></div>${buttons}</div>${renderInvoiceDocument(invoice,items)}`;
}
async function invoiceAction(action,id) {
  if(action==='pdf')return downloadInvoicePdf(id);
  if(action==='finalize'){if(!confirm('Finalize this invoice? This will update inventory and prevent draft editing.'))return;try{await api.post(`/api/invoices/${id}/finalize`,{});toast('Invoice finalized.');await renderInvoiceDetail(id);}catch(error){showError(error);}return;}
  if(action==='cancel'){if(!confirm('Cancel this invoice? The action will be recorded in the audit history.'))return;try{await api.post(`/api/invoices/${id}/cancel`,{});toast('Invoice cancelled.');await renderInvoiceDetail(id);}catch(error){showError(error);}return;}
  if(action==='payment')return openPaymentForm(id);
}
function openPaymentForm(id) {
  const invoice=state.currentInvoice;const due=Math.max(0,Number(invoice?.grandTotal||0)-Number(invoice?.amountPaid||0));
  openModal('Record a payment',`<form id="payment-form" data-submit="payment" data-id="${escapeHTML(id)}"><div class="notice"><div><strong>Outstanding balance</strong>${money(due)}</div></div><div class="form-grid"><div class="form-field"><label for="pay-amount">Amount received (₹) *</label><input id="pay-amount" name="amount" type="number" min="0.01" max="${due.toFixed(2)}" step="0.01" value="${due.toFixed(2)}" required></div><div class="form-field"><label for="pay-method">Payment method</label><select id="pay-method" name="method"><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Card</option><option>Cheque</option><option>Other</option></select></div><div class="form-field full"><label for="pay-note">Note</label><input id="pay-note" name="note"></div></div><div class="form-actions"><button class="btn btn-secondary" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save payment</button></div></form>`);
}
async function savePayment(form,values) {await api.post(`/api/invoices/${form.dataset.id}/payments`,{...values,amount:Number(values.amount)});closeModal();toast('Payment recorded.');await renderInvoiceDetail(form.dataset.id);}
async function updatePaymentStatus(id,status) {
  if(!status)return;try{if(status==='partially_paid')return openPaymentForm(id);await api.patch(`/api/invoices/${id}/payment-status`,{status});toast('Payment status updated.');await renderInvoiceDetail(id);}catch(error){showError(error);}
}

async function renderReports() {
  const data=await api.get('/api/reports/summary');const months=data.months||[];const taxes=data.taxBreakdown||[];
  pageContent.innerHTML=`${heading('Sales reports','A clear view of finalized sales and GST collected.','<button class="btn btn-secondary" data-action="download-csv">Export invoice CSV</button>')}<div class="stats-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));max-width:520px"><article class="stat-card"><div class="stat-label">Finalized invoices</div><div class="stat-value">${data.invoiceCount||0}</div><div class="stat-note">Cancelled and draft invoices are excluded</div></article><article class="stat-card"><div class="stat-label">GST split type</div><div class="stat-value">${taxes.length?taxes.length:0}</div><div class="stat-note">Based on finalized invoice supply states</div></article></div><div class="dashboard-columns"><section class="card"><div class="card-heading"><div><h3>Monthly summary</h3><p>Grouped by invoice month</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Month</th><th>Invoices</th><th>Sales</th><th>GST</th></tr></thead><tbody>${tableRows(months,(m)=>`<tr><td class="strong">${escapeHTML(m.month)}</td><td>${m.invoices}</td><td>${money(m.sales)}</td><td>${money(m.gst)}</td></tr>`,'No finalized invoice data yet.')}</tbody></table></div></section><section class="card"><div class="card-heading"><div><h3>GST breakdown</h3><p>Collected tax by transaction type</p></div></div>${taxes.length?taxes.map((t)=>`<div class="totals-row"><span>${escapeHTML(t.type)}</span><strong>${money(t.amount)}</strong></div>`).join(''):emptyState('₹','No GST data yet','GST summaries will appear after an invoice is finalized.')}</section></div>`;
}

