async function toggleMfa(enabled) {try{const result=await api.patch('/api/settings/security',{mfaEnabled:enabled});toast(result.message);await renderSettings();}catch(error){showError(error);await renderSettings();}}
async function uploadLogo(file) {if(!file)return;try{const form=new FormData();form.append('file',file);await api.post('/api/settings/logo',form);toast('Business logo uploaded.');await renderSettings();}catch(error){showError(error);}}
async function removeLogo() {if(!confirm('Remove the business logo from this profile? The stored file may remain in project storage.'))return;try{await api.delete('/api/settings/logo');toast('Logo removed from profile.');await renderSettings();}catch(error){showError(error);}}

async function downloadInvoicePdf(id) {
  try {
    const data = await api.get(`/api/invoices/${encodeURIComponent(id)}`);
    const invoice = data.invoice; const items = data.items || []; const JsPDF = window.jspdf?.jsPDF;
    if (!JsPDF) return toast('The PDF library did not load. Please refresh and try again.', 'error');
    const doc = new JsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pageWidth = doc.internal.pageSize.getWidth(); const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 14; const businessName = invoice.business?.businessName || 'GST Invoice';
    const headingLines = doc.splitTextToSize(businessName, 130);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(16); doc.text(headingLines, margin + 23, 20);
    doc.setFontSize(10); doc.text(invoice.docType === 'bill_of_supply' ? 'BILL OF SUPPLY' : 'TAX INVOICE', pageWidth - margin, 20, { align: 'right' });
    if (invoice.business?.logoUrl) { try { const image = await loadImage(invoice.business.logoUrl); doc.addImage(image, 'PNG', margin, 14, 18, 18); } catch {} }
    const seller = [invoice.business?.address, invoice.business?.state ? `${invoice.business.state} (${invoice.business.stateCode || ''})` : '', invoice.business?.gstin ? `GSTIN: ${invoice.business.gstin}` : '', invoice.business?.contactNumber, invoice.business?.email].filter(Boolean).join('\n');
    const invoiceMeta = [`Invoice: ${invoice.invoiceNumber}`, `Date: ${dateText(invoice.invoiceDate)}`, invoice.dueDate ? `Due: ${dateText(invoice.dueDate)}` : '', `Status: ${String(invoice.status || '').replaceAll('_', ' ')}`, `Payment: ${String(invoice.paymentStatus || 'unpaid').replaceAll('_', ' ')}`].filter(Boolean).join('\n');
    const firstStart = Math.max(31, 24 + headingLines.length * 7);
    doc.autoTable({ startY: firstStart, body: [[seller || 'Business details', invoiceMeta]], theme: 'plain', styles: { font: 'helvetica', fontSize: 8, cellPadding: 2, overflow: 'linebreak', valign: 'top' }, columnStyles: { 0: { cellWidth: 111 }, 1: { cellWidth: 71 } }, margin: { left: margin, right: margin, bottom: 16 } });
    const customer = invoice.customer || {};
    const billTo = [customer.name, customer.address, customer.state ? `${customer.state} (${customer.stateCode || ''})` : '', customer.gstin ? `GSTIN: ${customer.gstin}` : '', customer.mobile ? `Mobile: ${customer.mobile}` : '', customer.email].filter(Boolean).join('\n');
    const supply = [`Place of supply: ${invoice.placeOfSupply || customer.state || '—'}`, `Tax treatment: ${invoice.docType === 'bill_of_supply' ? 'No GST charged · Bill of Supply' : (invoice.intraState ? 'Intra-state · CGST + SGST' : 'Inter-state · IGST')}`].join('\n');
    doc.autoTable({ startY: doc.lastAutoTable.finalY + 3, head: [['BILL TO', 'SUPPLY DETAILS']], body: [[billTo || 'Customer', supply]], theme: 'grid', styles: { font: 'helvetica', fontSize: 8, cellPadding: 3, overflow: 'linebreak', valign: 'top' }, headStyles: { fillColor: [239, 246, 255], textColor: [30, 41, 59] }, columnStyles: { 0: { cellWidth: 111 }, 1: { cellWidth: 71 } }, margin: { left: margin, right: margin, bottom: 16 } });
    const body = items.map((item, index) => [String(index + 1), item.name, item.hsn || '—', `${item.quantity} ${item.unit || ''}`.trim(), `INR ${Number(item.unitPrice).toFixed(2)}`, `INR ${Number(item.taxable).toFixed(2)}`, `${Number(item.gstRate)}%`, `INR ${Number(item.gstAmount || 0).toFixed(2)}`, `INR ${Number(item.total).toFixed(2)}`]);
    doc.autoTable({ startY: doc.lastAutoTable.finalY + 5, head: [['#', 'Item', 'HSN/SAC', 'Qty', 'Unit price', 'Taxable', 'GST rate', 'GST amount', 'Total']], body, theme: 'grid', styles: { font: 'helvetica', fontSize: 6.6, cellPadding: 1.7, overflow: 'linebreak', valign: 'top' }, headStyles: { fillColor: [239, 246, 255], textColor: [30, 41, 59] }, columnStyles: { 0: { cellWidth: 6 }, 1: { cellWidth: 36 }, 2: { cellWidth: 17 }, 3: { cellWidth: 14 }, 4: { cellWidth: 21 }, 5: { cellWidth: 20 }, 6: { cellWidth: 14 }, 7: { cellWidth: 24 }, 8: { cellWidth: 30 } }, margin: { left: margin, right: margin, bottom: 16 }, rowPageBreak: 'avoid' });
    const totals = [['Subtotal', `INR ${Number(invoice.subtotal || 0).toFixed(2)}`], ['Total discount', `- INR ${Number(invoice.totalDiscount || 0).toFixed(2)}`], ['Taxable value', `INR ${Number(invoice.taxableValue || 0).toFixed(2)}`], ...(invoice.intraState ? [['CGST', `INR ${Number(invoice.cgst || 0).toFixed(2)}`], ['SGST', `INR ${Number(invoice.sgst || 0).toFixed(2)}`]] : [['IGST', `INR ${Number(invoice.igst || 0).toFixed(2)}`]]), ['Other charges', `INR ${Number(invoice.otherCharges || 0).toFixed(2)}`], ['Round-off', `INR ${Number(invoice.roundOff || 0).toFixed(2)}`], ['Amount payable', `INR ${Number(invoice.grandTotal || 0).toFixed(2)}`]];
    doc.autoTable({ startY: doc.lastAutoTable.finalY + 5, body: totals, theme: 'plain', styles: { font: 'helvetica', fontSize: 8.5, cellPadding: 1.8 }, columnStyles: { 0: { cellWidth: 43 }, 1: { cellWidth: 48, halign: 'right' } }, margin: { left: pageWidth - margin - 43 - 48, right: margin, bottom: 16 }, didParseCell: (hook) => { if (hook.row.index === totals.length - 1) hook.cell.styles.fontStyle = 'bold'; } });
    const details = [['Amount in words', amountWords(invoice.grandTotal || 0)], ['Payment status', String(invoice.paymentStatus || 'unpaid').replaceAll('_', ' ')]];
    if (invoice.notes) details.push(['Notes', invoice.notes]);
    if (invoice.terms) details.push(['Terms and conditions', invoice.terms]);
    const bank = invoice.business?.bankDetails || {};
    if (bank.bankName || bank.bankAccount) details.push(['Bank details', [bank.bankName, bank.bankAccount, bank.bankIfsc ? `IFSC ${bank.bankIfsc}` : ''].filter(Boolean).join(' · ')]);
    doc.autoTable({ startY: doc.lastAutoTable.finalY + 4, body: details, theme: 'plain', styles: { font: 'helvetica', fontSize: 8, cellPadding: 2, overflow: 'linebreak', valign: 'top' }, columnStyles: { 0: { cellWidth: 38, fontStyle: 'bold' }, 1: { cellWidth: pageWidth - margin * 2 - 38 } }, margin: { left: margin, right: margin, bottom: 18 }, rowPageBreak: 'auto' });
    let footerY = doc.lastAutoTable.finalY + 20;
    if (footerY > pageHeight - 14) { doc.addPage(); footerY = 22; }
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.text('Thank you for your business.', margin, footerY);
    doc.setDrawColor(100, 116, 139); doc.line(pageWidth - 80, footerY - 2, pageWidth - margin, footerY - 2);
    doc.setFontSize(7); doc.text('Authorized signature', pageWidth - 55, footerY + 3, { align: 'center' });
    const pageCount = doc.getNumberOfPages();
    for (let page = 1; page <= pageCount; page += 1) { doc.setPage(page); doc.setFontSize(7); doc.text(`Page ${page} of ${pageCount}`, pageWidth - margin, pageHeight - 7, { align: 'right' }); }
    doc.save(`${String(invoice.invoiceNumber || 'invoice').replace(/[^a-z0-9-_]/gi, '_')}.pdf`);
  } catch (error) { showError(error); }
}
function loadImage(url) {return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);resolve(canvas.toDataURL('image/png'));};image.onerror=reject;image.src=url;});}
async function downloadCsv() {try{const response=await fetch('/api/exports/invoices.csv',{credentials:'same-origin'});if(!response.ok){const data=await response.json().catch(()=>({}));throw new ApiError(data.message||'Could not export invoices.',response.status);}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='gst-invoices.csv';a.click();URL.revokeObjectURL(url);}catch(error){showError(error);}}

async function handleSubmit(event) {
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const values=Object.fromEntries(new FormData(form).entries());
  try {
    if(form.id==='login-form'){const result=await api.post('/api/auth/login',values);if(result.requiresOtp){showAuth('otp');return;}setCsrfToken(result.csrfToken);state.user=result.user;state.profile=result.profile;state.page='dashboard';enterApp();return;}
    if(form.id==='register-form'){const result=await api.post('/api/auth/register',values);setCsrfToken(result.csrfToken);state.user=result.user;state.profile=result.profile;state.page='dashboard';enterApp();return;}
    if(form.id==='otp-form'){const result=await api.post('/api/auth/verify-otp',values);setCsrfToken(result.csrfToken);state.user=result.user;state.profile=result.profile;state.page='dashboard';enterApp();return;}
    if(form.id==='forgot-form'){const result=await api.post('/api/auth/forgot-password',values);if(result.emailConfigured===false){showAuth('forgot','Email delivery is not configured yet. Ask the account owner to add SMTP settings.');return;}showAuth('reset',result.message);$('#reset-email').value=values.email;return;}
    if(form.id==='reset-form'){const result=await api.post('/api/auth/reset-password',values);showAuth('login',result.message);return;}
    const handler=form.dataset.submit;if(handler==='customer')return await saveCustomer(form,values);if(handler==='product')return await saveProduct(form,values);if(handler==='profile')return await saveProfile(form,values);if(handler==='invoice')return await saveInvoiceFromEditor();if(handler==='payment')return await savePayment(form,values);
  } catch(error) {const message=$('#auth-message');if(message&&!appShell.hidden)showError(error);else if(message)message.textContent=error.message;else showError(error);}
}
async function handleClick(event) {
  const target=event.target.closest('[data-action],[data-nav],[data-view-invoice],[data-edit-customer],[data-edit-product],[data-view-product],[data-remove-customer],[data-remove-product],[data-customer-history],[data-invoice-action]');if(!target)return;
  if(target.dataset.nav){event.preventDefault();return navigate(target.dataset.nav);}
  if(target.dataset.viewInvoice){closeModal();return navigate('invoice-detail',target.dataset.viewInvoice);}
  if(target.dataset.editCustomer)return editCustomer(target.dataset.editCustomer);
  if(target.dataset.editProduct)return editProduct(target.dataset.editProduct);
  if(target.dataset.viewProduct)return showProductDetails(target.dataset.viewProduct);
  if(target.dataset.removeCustomer)return removeCustomer(target.dataset.removeCustomer);
  if(target.dataset.removeProduct)return removeProduct(target.dataset.removeProduct);
  if(target.dataset.customerHistory)return showCustomerHistory(target.dataset.customerHistory);
  if(target.dataset.invoiceAction)return invoiceAction(target.dataset.invoiceAction,target.dataset.id);
  const action=target.dataset.action;
  if(action==='show-register')return showAuth('register');if(action==='show-login')return showAuth('login');if(action==='forgot')return showAuth('forgot');
  if(action==='resend-otp'){try{await api.post('/api/auth/resend-otp',{});toast('A new verification code has been sent.');}catch(error){showError(error);}return;}
  if(action==='logout'){try{await api.post('/api/auth/logout',{});}catch{}setCsrfToken('');state.user=null;state.profile=null;showAuth('login');return;}
  if(action==='new-invoice')return openInvoiceEditor();if(action==='add-customer')return editCustomer('new');if(action==='add-product')return editProduct('new');
  if(action==='close-modal'){if(target===event.target||target.closest('[data-modal-content]')){if(!target.closest('[data-modal-content]')||target.closest('button'))closeModal();}return;}
  if(action==='menu'){const open=$('#sidebar').classList.toggle('open');$('.mobile-overlay')?.classList.toggle('show',open);return;}
  if(action==='retry')return navigate(state.page);if(action==='preview-invoice')return previewInvoice();if(action==='add-line')return addInvoiceLine();if(action==='remove-line'){const row=target.closest('.invoice-line');if($$('.invoice-line').length<=1){row?.querySelectorAll('input').forEach((field)=>field.value=field.dataset.lineField==='quantity'?'1':field.dataset.lineField==='unit'?'pcs':'');if(row)row.querySelector('[data-line-field="productId"]').value='';if(row)row.querySelector('[data-line-field="gstRate"]').value='0';}else row?.remove();recalculateEditor();return;}
  if(action==='save-invoice')return saveInvoiceFromEditor();if(action==='download-pdf')return downloadInvoicePdf(target.dataset.id);if(action==='print-invoice'){window.print();return;}if(action==='download-csv')return downloadCsv();
  if(action==='upload-logo')return $('#logo-file')?.click();if(action==='remove-logo')return removeLogo();
}
let searchTimer;
document.addEventListener('submit',handleSubmit);
document.addEventListener('click',handleClick);
async function refreshSearch(selector, position, render) {
  try {
    await render();
    const input = $(selector);
    if (input) { input.focus(); if (Number.isInteger(position) && input.setSelectionRange) input.setSelectionRange(position, position); }
  } catch (error) { showError(error); }
}
document.addEventListener('input',(event)=>{
  if (event.target.matches('[data-filter="search"]')) {
    const input=event.target, position=input.selectionStart; clearTimeout(searchTimer);
    searchTimer=setTimeout(()=>refreshSearch('[data-filter="search"]',position,()=>renderInvoices(currentInvoiceFilters())),250);
  }
  if (event.target.matches('[data-search="customers"]')) {
    const value=event.target.value, position=event.target.selectionStart; clearTimeout(searchTimer);
    searchTimer=setTimeout(()=>refreshSearch('[data-search="customers"]',position,()=>renderCustomers(value)),250);
  }
  if (event.target.matches('[data-search="products"]')) {
    const value=event.target.value, position=event.target.selectionStart; clearTimeout(searchTimer);
    searchTimer=setTimeout(()=>refreshSearch('[data-search="products"]',position,()=>renderProducts(value)),250);
  }
  if ($('#invoice-form') && event.target.closest('#invoice-form')) recalculateEditor();
});
document.addEventListener('change',(event)=>{
  if(event.target.id==='inv-customer')syncCustomerSelection();
  if(event.target.id==='cust-type')$('#cust-gstin').required=event.target.value==='registered';
  if(event.target.id==='inv-cust-type')$('#inv-cust-gstin').required=event.target.value==='registered';
  if(event.target.id==='inv-type')syncDocumentType();
  if(event.target.matches('[data-line-field="productId"]'))syncProductSelection(event.target);
  if(event.target.matches('[data-filter="stock"]')){state.productStockFilter=event.target.value;renderProducts($('[data-search="products"]')?.value||'').catch(showError);return;}
  if(['paymentStatus','from','to','minAmount','maxAmount'].includes(event.target.dataset.filter))renderInvoices(currentInvoiceFilters()).catch(showError);
  if(event.target.matches('[data-payment-status]'))updatePaymentStatus(event.target.dataset.paymentStatus,event.target.value);
  if(event.target.matches('[data-action="toggle-mfa"]'))toggleMfa(event.target.checked);
  if(event.target.id==='logo-file')uploadLogo(event.target.files?.[0]);
  if($('#invoice-form')&&event.target.closest('#invoice-form'))recalculateEditor();
});
window.addEventListener('popstate',()=>{const parts=location.pathname.split('/').filter(Boolean);if(parts[0]==='invoices'&&parts[1])navigate('invoice-detail',decodeURIComponent(parts[1]),false);else navigate(navItems.some(([page])=>page===(parts[0]||'dashboard'))?(parts[0]||'dashboard'):'dashboard','',false);});

async function renderInvoiceRowsFromFilters() { return renderInvoices(currentInvoiceFilters()); }
function openModal(title,content,wide=false) {modalRoot.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}" data-modal-content><div class="modal-heading"><div><h2>${escapeHTML(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div>${content}</section></div>`;}
function closeModal(){modalRoot.innerHTML='';}
bootstrap();
